

from typing import List
import heapq


class Solution:
    
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        countObj = {}
        posObj = {}
        for i, v in enumerate(nums):
            if v not in countObj.keys():
                countObj[v] = 0
                posObj[v] = i
                
            countObj[v] += 1
            
        sortedArray = heapq.nlargest(k, countObj.items(), key=lambda x: x[1])
        
        return sorted([x[0] for x in sortedArray], key=lambda x: posObj[x])
            
    
    
